import DSA5 from '../../config/config-dsa5.js';
import DSA5_Utility from '../helpers/utility-dsa5.js';
import { showPatchViewer } from '../maintenance/migrator.js';
import RuleChaos from '../rules/rule_chaos.js';
import { showPopout } from '../../hooks/imagepopouttochat.js';
import GroupCheck from '../rolls/group-check.js';
import ChatCommandService from './chat_command_service.js';
import RollRequestService from '../queries/roll-request.js';
import ItempackageData from '../../data/item/itempackage.js';

const { duplicate } = foundry.utils;
const { renderTemplate } = foundry.applications.handlebars;

export default class DSA5ChatListeners {
  static chatListeners(html) {
    html.on('click', '.openJournalBrowser', () => game.dsa5.apps.journalBrowser.render(true));
    html.on('click', '.openBookInJournalBrowser', async (ev) => {
      const book = ev.currentTarget.dataset.book;
      const bookType = ev.currentTarget.dataset.type || 'books';
      await game.dsa5.apps.journalBrowser.render(false);
      await game.dsa5.apps.journalBrowser.loadBook(book, $(game.dsa5.apps.journalBrowser.element), bookType);
      await game.dsa5.apps.journalBrowser.render(true);
    });

    const helpButton = $(`<button type="button" class="ui-control icon fas fa-question" data-tooltip="HELP.showHelp" aria-label="Help"></button>`);
    html.find('.control-buttons').prepend(helpButton);
    new foundry.applications.ux.ContextMenu(html[0], '.fa-question', [], {
      eventName: 'click',
      onOpen: DSA5ChatListeners._onHelpContextMenu,
      jQuery: false,
      fixed: true,
    });
    html.on('click', '.showPatchViewer', () => showPatchViewer());
    html.on('click', '.functionswitch', (ev) => RuleChaos[ev.currentTarget.dataset.function](ev));
    html.on('click', '.panToToken', (ev) => DSA5ChatListeners.panToToken(ev));
    html.on('click', '.popoutImage', (ev) => showPopout(ev));
  }

  static async panToToken(ev) {
    const token = await fromUuid(ev.currentTarget.dataset.uuid);
    if (!token) return;

    canvas.animatePan({ x: token.x, y: token.y });

    if (!token.isOwner) return;

    token.object.control({ releaseOthers: true });
  }

  static postStatus(id) {
    const effect = CONFIG.statusEffects.find((x) => x.id == id);
    if (!effect) return;

    const description = effect.description || effect.name;
    const msg = `<h2><a class="chat-condition chatButton" data-id="${id}"><img class="sender-image" style="background-color:black;margin-right: 8px;" src="${effect.img}"/>${_loc(effect.name)}</h2></a><p>${_loc(description)}</p>`;
    ChatMessage.create(DSA5_Utility.chatDataSetup(msg, 'roll'));
  }

  static getHelp() {
    const msg =
      DSA5.helpContent
        .map(
          (x) => `<h4>${_loc(`HELP.${x.name}`)}</h4>
            <p><b>${_loc('HELP.command')}</b>: ${x.command}</p>
            <p><b>${_loc('HELP.example')}</b>: ${x.example}</p>
            <p><b>${_loc('Description')}</b>: ${_loc(`HELP.descr${x.name}`)}</p>`,
        )
        .join('') + `<p>${_loc('HELP.default')}</p>`;
    ChatMessage.create(DSA5_Utility.chatDataSetup(msg, 'roll'));
  }

  static showConditions() {
    const effects = duplicate(CONFIG.statusEffects)
      .map((x) => {
        x.name = _loc(x.name);
        return x;
      })
      .sort((a, b) => {
        return a.name.localeCompare(b.name);
      });
    const msg = effects.map((x) => `<a class="chat-condition chatButton" data-id="${x.id}"><img src="${x.img}"/>${x.name}</a>`).join(' ');
    ChatMessage.create(DSA5_Utility.chatDataSetup(msg, 'roll'));
  }

  static async check3D20(target, skill, options = {}) {
    let attrs = 12;
    let json = {};
    if (target) {
      skill = await DSA5_Utility.skillByName(skill || target.textContent);
      if (target.dataset.attrs) attrs = target.dataset.attrs.split('|');
      if (target.dataset.json) json = JSON.parse(decodeURIComponent(target.dataset.json));
    } else if (skill) {
      skill = await DSA5_Utility.skillByName(skill);
    }
    if (skill) skill = skill.toObject();

    if (!skill) {
      skill = {
        name: '3d20',
        type: 'skill',
        system: {
          talentValue: { value: 0 },
          characteristic1: { value: 'mu' },
          characteristic2: { value: 'kl' },
          characteristic3: { value: 'in' },
          RPr: { value: 'no' },
          burden: { value: 'no' },
        },
      };
    }

    const actor = DSA5_Utility.emptyActor(attrs);

    if (json.attrs) {
      const attrs = json.attrs.split(',');

      for (let i = 1; i <= attrs.length; i++) {
        actor.system.characteristics[skill.system[`characteristic${i}`].value].initial = Number(attrs[i - 1]) || 12;
      }
      actor.prepareData();
    }
    skill.system.talentValue.value = Number(json.fw) || 0;

    actor.setupSkill(skill, options, 'emptyActor').then((setupData) => {
      actor.basicTest(setupData);
    });
  }

  static async showTables() {
    const msg = await renderTemplate('systems/dsa5/templates/tables/systemtables.hbs', { tables: DSA5.systemTables });
    ChatMessage.create(DSA5_Utility.chatDataSetup(msg, 'roll'));
  }

  static _onHelpContextMenu() {
    ui.context.menuItems = [
      { label: _loc('HELP.showHelp'), icon: 'fas fa-question', onClick: () => DSA5ChatListeners.getHelp() },
      game.user.isGM ? { label: _loc('HELP.pay'), icon: 'fas fa-coins', onClick: () => ChatCommandService.openPaymentDialog('pay') } : null,
      game.user.isGM ? { label: _loc('HELP.getPaid'), icon: 'fas fa-hand-holding-usd', onClick: () => ChatCommandService.openPaymentDialog('getPaid') } : null,
      {
        label: _loc('HELP.quickAbility'),
        icon: 'fas fa-bolt',
        onClick: () =>
          ChatCommandService.openSkillActorDialog('HELP.quickAbility', {
            onSubmit: (name, type, modifier, actorIds) => {
              for (const id of actorIds) {
                const actor = game.actors.get(id);
                if (actor) ChatCommandService.executeAbilityRoll(actor, name, type, undefined, { modifier });
              }
            },
          }),
      },
      { label: _loc('HELP.conditions'), icon: 'fas fa-biohazard', onClick: () => DSA5ChatListeners.showConditions() },
      { label: _loc('HELP.tables'), icon: 'fas fa-table', onClick: () => DSA5ChatListeners.showTables() },
      { label: _loc('HELP.packages'), icon: 'fas fa-box', onClick: () => ItempackageData.postPackagesChatCard() },
      {
        label: _loc('HELP.request'),
        icon: 'fas fa-dice',
        onClick: () => RollRequestService.openRequestDialog(),
      },
      { label: _loc('HELP.threeD20Check'), icon: 'fas fa-dice-d20', onClick: () => DSA5ChatListeners.check3D20() },
      {
        label: _loc('HELP.groupcheck'),
        icon: 'fas fa-users',
        onClick: () => GroupCheck.openDialog(),
      },
    ].filter(Boolean);
  }
}
