import DSA5 from '../config/config-dsa5.js';
import RuleChaos from '../system/rules/rule_chaos.js';
import DSA5_Utility from '../system/helpers/utility-dsa5.js';
const { getProperty } = foundry.utils;
const { renderTemplate } = foundry.applications.handlebars;

function itemId(itemData) {
  return itemData?._id || itemData?.id;
}

export const dropToGround = async (sourceActor, item, data, formOptions) => {
  const amount = formOptions.count.value;
  const isBag = formOptions.isBag?.value;

  if (game.user.isGM) {
    const items = await game.dsa5.apps.DSA5_Utility.allMoneyItems();
    const folder = await DSA5_Utility.getFolderForType('Actor', null, 'Dropped Items');
    const userIds = game.users.filter((x) => !x.isGM).map((x) => x.id);

    const ownership = userIds.reduce(
      (prev, cur) => {
        prev[cur] = 1;
        return prev;
      },
      { default: 0 },
    );

    const newItem = item.toObject();
    newItem.system.quantity.value = amount;
    newItem.system.parent_id = '';
    RuleChaos.obfuscateDropData(newItem, data.tabsinvisible);

    if (getProperty(newItem, 'system.worn.value')) newItem.system.worn.value = false;

    let bagItems = [];
    if (isBag) {
      bagItems = fetchBagItems(item, sourceActor).map((i) => {
        const itemData = i.toObject();
        if (getProperty(itemData, 'system.worn.value')) itemData.system.worn.value = false;
        return itemData;
      });
    }

    const actor = {
      type: 'npc',
      name: item.name,
      img: item.img,
      prototypeToken: {
        texture: {
          scaleX: 1,
          scaleY: 1,
          src: item.img,
        },
        width: 0.4,
        height: 0.4,
      },
      ownership,
      items: [...items, newItem, ...bagItems],
      flags: { core: { sheetClass: 'dsa5.MerchantSheetDSA5' } },
      folder,
      system: {
        merchant: {
          merchantType: 'loot',
          temporary: true,
          hidePlayer: 1,
        },
        status: { wounds: { value: 16 } },
      },
    };
    const finalActor = await game.dsa5.entities.Actordsa5.create(actor);
    const td = await finalActor.getTokenDocument({
      x: data.x,
      y: data.y,
      hidden: false,
    });
    if (!canvas.dimensions.rect.contains(td.x, td.y)) return false;

    if (sourceActor) {
      await canvas.scene.createEmbeddedDocuments('Token', [td], {
        noHook: true,
      });
      const newCount = item.system.quantity.value - amount;
      if (newCount < 1) {
        await sourceActor.deleteEmbeddedDocuments('Item', [item.id]);
      } else {
        await sourceActor.updateEmbeddedDocuments('Item', [{ _id: item.id, 'system.quantity.value': newCount }]);
      }
      if (bagItems.length > 0) {
        await sourceActor.deleteEmbeddedDocuments('Item', bagItems.map((i) => i._id));
      }
    } else {
      await canvas.scene.createEmbeddedDocuments('Token', [td]);
    }
  } else {
    const payload = {
      itemId: item.uuid,
      sourceActorId: sourceActor?.id,
      data,
      amount,
      isBag,
    };
    game.socket.emit('system.dsa5', {
      type: 'itemDrop',
      payload,
    });
  }
};

export function fetchBagItems(item, sourceActor) {
  const bagItems = [];
  for (const i of sourceActor.items) {
    if (i.system.parent_id == item.id) {
      bagItems.push(i);
      if (i.system.isBagWithContents) {
        const bagItems2 = fetchBagItems(i, sourceActor);
        bagItems.push(...bagItems2);
      }
    }
  }
  return bagItems;
}

/**
 * Collect bag item objects grouped by depth level for ordered creation.
 * Returns { bagData, childrenByDepth } where childrenByDepth is a Map<depth, itemData[]>.
 */
function collectBagContentsGrouped(bagItemData, sourceActor) {
  const childrenByDepth = new Map();

  function collect(parentId, depth) {
    const children = [];
    for (const i of sourceActor.items) {
      if (i.system.parent_id == parentId) {
        const obj = i.toObject();
        children.push(obj);
        if (!childrenByDepth.has(depth)) childrenByDepth.set(depth, []);
        childrenByDepth.get(depth).push(obj);
        if (i.system.isBagWithContents) {
          collect(itemId(i), depth + 1);
        }
      }
    }
    return children;
  }

  collect(itemId(bagItemData), 1);
  return childrenByDepth;
}

/**
 * Transfer a bag with all its contents from one actor to another,
 * remapping parent_id references so the bag hierarchy is preserved.
 * @param {Actor} sourceActor - The actor to take the bag from
 * @param {Actor} targetActor - The actor to give the bag to
 * @param {Object} bagItemData - The bag item as plain object data
 * @returns {Promise<Object>} The created bag item on the target actor
 */
export async function transferBagWithContents(sourceActor, targetActor, bagItemData) {
  const { duplicate } = foundry.utils;

  // Collect all children grouped by depth for ordered processing
  const childrenByDepth = collectBagContentsGrouped(bagItemData, sourceActor);
  const allChildren = [...childrenByDepth.values()].flat();

  // Track old ID -> new ID mappings for parent_id remapping
  const idMap = new Map();

  // Create the bag itself on the target
  const bagCopy = duplicate(bagItemData);
  bagCopy.system.parent_id = '';
  if (bagCopy.system.worn?.value) bagCopy.system.worn.value = false;
  delete bagCopy._id;

  const [createdBag] = await targetActor.createEmbeddedDocuments('Item', [bagCopy], { render: false });
  idMap.set(itemId(bagItemData), createdBag.id);

  // Create children depth by depth so parent bags exist before their children
  const depths = [...childrenByDepth.keys()].sort((a, b) => a - b);
  for (const depth of depths) {
    const items = childrenByDepth.get(depth);
    const copies = items.map((item) => {
      const copy = duplicate(item);
      // Remap parent_id using the id map
      const newParentId = idMap.get(copy.system.parent_id);
      if (newParentId) copy.system.parent_id = newParentId;
      if (copy.system.worn?.value) copy.system.worn.value = false;
      delete copy._id;
      return copy;
    });
    const created = await targetActor.createEmbeddedDocuments('Item', copies, { render: false });
    // Record new IDs for any sub-bags at this depth
    for (let idx = 0; idx < items.length; idx++) {
      idMap.set(itemId(items[idx]), created[idx].id);
    }
  }

  // Delete bag + all children from source
  const deleteIds = [itemId(bagItemData), ...allChildren.map((c) => itemId(c))].filter(Boolean);
  const existingIds = deleteIds.filter((id) => sourceActor.items.has(id));
  if (existingIds.length > 0) {
    await sourceActor.deleteEmbeddedDocuments('Item', existingIds, { render: false });
  }

  return createdBag;
}

const handleItemDrop = async (canvas, data) => {
  const item = await Item.implementation.fromDropData(data);

  if (!(game.settings.get('dsa5', 'enableItemDropToCanvas') || game.user.isGM || data.tokenId)) return;

  const sourceActor = item.parent;

  if (item.type == 'trap') {
    await item.system.createRegionBehavior(data);
    return;
  }

  if (!DSA5.equipmentCategories.has(item.type)) return;

  const callback = async (formOptions) => {
    dropToGround(sourceActor, item, data, formOptions);
  };

  const isBag = item.system.isBagWithContents && sourceActor;

  RangeSelectDialog.create('DSASETTINGS.enableItemDropToCanvas', callback, {
    name: _loc('MERCHANT.dropGround', { name: item.name }),
    count: item.system.quantity.value,
    isBag
  });
};

const handleGroupDrop = async (canvas, data) => {
  const scene = canvas.scene;
  const ids = data.ids?.filter((id) => game.actors.has(id)) || [];
  if (!scene || !ids.length) return;

  const gridSize = scene.grid.size || canvas.grid?.size || canvas.dimensions?.size || 0;
  const rowLength = Math.ceil(Math.sqrt(ids.length));
  const tokens = [];
  for (const [index, id] of ids.entries()) {
    const actor = game.actors.get(id);
    const x = data.x + (index % rowLength) * gridSize;
    const y = data.y + Math.floor(index / rowLength) * gridSize;
    const tokenDocument = await actor.getTokenDocument({ x, y, hidden: false }, { parent: scene });
    tokens.push(tokenDocument.toObject?.() ?? tokenDocument);
  }

  await scene.createEmbeddedDocuments('Token', tokens);
};

export const connectHook = () => {
  Hooks.on('dropCanvasData', async (canvas, data) => {
    if (data.type == 'GroupDrop') {
      handleGroupDrop(canvas, data);
      return false;
    } else if (data.type == 'Item') {
      handleItemDrop(canvas, data);
      return false;
    }
  });
};

export class RangeSelectDialog extends foundry.applications.api.DialogV2 {
  static async content(data) {
    return await renderTemplate('systems/dsa5/templates/dialog/dropToGround.hbs', data);
  }

  static async create(title, callback, data) {
    if (!data.min) data.min = 1;
    if (!data.max) data.max = data.count;
    const content = await this.content(data)

    new RangeSelectDialog({
      window: {
        title,
      },
      content,
      buttons: [
        {
          action: 'yes',
          icon: 'fa fa-check',
          label: 'yes',
          default: true,
          callback: (event, button, dialog) => {
            callback(button.form.elements);
          },
        },
        {
          action: 'no',
          icon: 'fas fa-times',
          label: 'cancel',
        },
      ],
    }).render(true);
  }

  async _onRender(context, options) {
    await super._onRender(context, options);

    const html = $(this.element);
    html.find('input[type="range"]').on('change', (ev) => {
      $(ev.currentTarget).closest('.row-section').find('.range-value').html($(ev.currentTarget).val());
    });
  }
}
