import Actordsa5 from '../../actor/actor-dsa5.js';
import OnUseEffect from '../automation/onUseEffects.js';
import Riding from '../automation/riding.js';
import RuleChaos from '../rules/rule_chaos.js';
import DSA5_Utility from '../helpers/utility-dsa5.js';
import { tinyNotification } from '../helpers/view_helper.js';
import PaymentRequestService from '../queries/payment-requests.js';
import { Trade } from '../../actor/trade.js';
import DSA5StatusEffects from '../../status/status_effects.js';
import { DefaultAppv2 } from '../../actor/baseapp.js';
import { ItemDataModel } from '../../data/baseitem.js';
import CombatskillData from '../../data/item/combatskill.js';
import { ITEM_CONSTANTS } from '../../config/item-constants.js';
import { RollDialogBuilder } from '../../dialog/dialog-builder.js';
import { resolveHotbarActorContext } from '../helpers/hotbar_actor.js';
import { DICE_CONSTANTS } from '../../config/dice-constants.js';
import { DSACalendarEntry } from '../../data/journal/dsacalendar.js';
import { DSAQuestLogEntry } from '../../data/journal/dsaquestlog.js';
const { mergeObject, duplicate } = foundry.utils;
const { renderTemplate } = foundry.applications.handlebars;

export default class TokenHotbar2 extends DefaultAppv2 {
  static attackTypes = new Set(['meleeweapon', 'rangeweapon']);
  static traitTypes = new Set(['meleeAttack', 'rangeAttack']);
  static spellTypes = new Set(['liturgy', 'spell']);

  static registerTokenHotbar() {
    if (!game.dsa5.apps.tokenHotbar) {
      game.dsa5.apps.tokenHotbar = new TokenHotbar2();
      game.dsa5.apps.tokenHotbar.updateDSA5Hotbar(undefined, true);
      if (!game.settings.get('dsa5', 'disableTokenhotbar')) game.dsa5.apps.tokenHotbar.render(true);

      Hooks.call('dsa5TokenHotbarReady', game.dsa5.apps.tokenHotbar);
    }
  }

  constructor(options) {
    super(options);
    this.searching = '';

    TokenHotbar2.combatSkills = ['selfControl', 'featOfStrength', 'bodyControl', 'perception', 'loyalty'].map((x) => _loc(`LocalizedIDs.${x}`));
    TokenHotbar2.defaultSkills = new Set([_loc('LocalizedIDs.perception')]);

    if (game.user.isGM) {
      this.callbackFunctions = {};
      const setting = game.settings.get('dsa5', 'enableMasterTokenFunctions');
      this.gmItems = [
        {
          name: 'gmMenu',
          disabled: setting.masterMenu,
          icon: 'systems/dsa5/icons/categories/DSA-Auge.webp',
          id: 'masterMenu',
          cssClass: 'gm',
          abbrev: '',
          subfunction: 'gm',
        },
        {
          name: 'MASTER.randomPlayer',
          disabled: setting.randomVictim,
          iconClass: 'fa fa-dice-six',
          id: 'randomVictim',
          cssClass: 'gm',
          abbrev: '',
          subfunction: 'gm',
        },
        {
          name: 'TT.tokenhotbarMoney',
          disabled: setting.payMoney,
          icon: 'systems/dsa5/icons/money-D.webp',
          id: 'payMoney',
          cssClass: 'gm',
          abbrev: '',
          subfunction: 'gm',
        },
        {
          name: 'dsacalendar.createEvent',
          disabled: setting.createCalendarEvent,
          iconClass: 'fas fa-calendar-day',
          id: DSACalendarEntry.HOTBAR_ID,
          cssClass: 'gm',
          abbrev: '',
          subfunction: 'gm',
        },
        {
          name: 'DSAQUESTLOG.createQuest',
          disabled: setting.createQuest,
          iconClass: 'fas fa-scroll',
          id: DSAQuestLogEntry.HOTBAR_ID,
          cssClass: 'gm',
          abbrev: '',
          subfunction: 'gm',
        },
      ];
    }

    Hooks.on('controlToken', (elem, controlTaken) => {
      game.dsa5.apps.tokenHotbar?.updateDSA5Hotbar(undefined, true);
    });

    Hooks.on('updateActor', (actor, updates) => {
      game.dsa5.apps.tokenHotbar?.updateDSA5Hotbar(actor.id);
    });

    Hooks.on('updateToken', (tokenDoc, changed, options) => {
      game.dsa5.apps.tokenHotbar?.updateDSA5Hotbar(tokenDoc.actor?.id);
    });

    Hooks.on('recordToken', (tokenDoc) => {
      if (game.combat) game.combat.handleMovementCost(tokenDoc);
      game.dsa5.apps.tokenHotbar?.updateDSA5Hotbar(tokenDoc.actor?.id);
    });

    Hooks.on('updateCombatant', (combatant, changes) => {
      game.dsa5.apps.tokenHotbar?.updateDSA5Hotbar(combatant.actor?.id);
    });

    Hooks.on('updateOwnedItem', (source, item) => {
      game.dsa5.apps.tokenHotbar?.updateDSA5Hotbar(source.data.id);
    });

    Hooks.on('createOwnedItem', (source, item) => {
      game.dsa5.apps.tokenHotbar?.updateDSA5Hotbar(source.data.id);
    });

    Hooks.on('deleteOwnedItem', (source, item) => {
      game.dsa5.apps.tokenHotbar?.updateDSA5Hotbar(source.data.id);
    });

    Hooks.on('updateItem', (source, item) => {
      const id = source.parent?.id;
      if (id) game.dsa5.apps.tokenHotbar?.updateDSA5Hotbar(id);
    });

    Hooks.on('createItem', (source, item) => {
      const id = source.parent?.id;
      if (id) game.dsa5.apps.tokenHotbar?.updateDSA5Hotbar(id);
    });

    Hooks.on('deleteItem', (source, item) => {
      const id = source.parent?.id;
      if (id) game.dsa5.apps.tokenHotbar?.updateDSA5Hotbar(id);
    });

    Hooks.on('deleteActiveEffect', (effect, options) => {
      const id = effect.parent?.id;
      if (id) game.dsa5.apps.tokenHotbar?.updateDSA5Hotbar(id);
    });

    Hooks.on('updateActiveEffect', (effect, options) => {
      const id = effect.parent?.id;
      if (id) game.dsa5.apps.tokenHotbar?.updateDSA5Hotbar(id);
    });

    Hooks.on('createActiveEffect', (effect, options) => {
      const id = effect.parent?.id;
      if (id) game.dsa5.apps.tokenHotbar?.updateDSA5Hotbar(id);
    });

    Hooks.on('canvasInit', () => {
      if (!this.rendered) return;

      game.dsa5.apps.tokenHotbar?.updateDSA5Hotbar(undefined, true);
    });
  }

  registerMasterFunction(entry, callback) {
    const setting = game.settings.get('dsa5', 'enableMasterTokenFunctions');
    entry.disabled = setting[entry.id];
    this.gmItems.push(entry);
    this.callbackFunctions[entry.id] = callback;
  }

  async prepareSkills() {
    const skills = await DSA5_Utility.allSkills();
    this.skills = skills.map((x) => {
      return {
        name: x.name,
        icon: x.img,
        id: x.name,
        cssClass: 'skillgm',
        addClass: x.system.group.value,
        abbrev: x.name[0],
        subfunction: 'skillgm',
      };
    });
    this.skills = this.skills.sort((a, b) => {
      return a.addClass.localeCompare(b.addClass) || a.name.localeCompare(b.name);
    });
    return this.skills;
  }

  static hookUpdate(changeId) {
    if (changeId == game.dsa5.apps.tokenHotbar?.actor?.id) game.dsa5.apps.tokenHotbar.updateDSA5Hotbar();
    else if (ui.hotbar.token?.actor?.id == changeId) ui.hotbar.updateDSA5Hotbar();
  }

  resetPosition() {
    const hotbarPosition = $('#hotbar').first().position();
    const itemWidth = game.settings.get('dsa5', 'tokenhotbarSize');
    this.setPosition({ left: hotbarPosition.left + 8, top: hotbarPosition.top - itemWidth - 25 });
  }

  static DEFAULT_OPTIONS = {
    classes: ['dsa5', 'tokenQuickHot'],
    window: {
      frame: false,
    },
  };

  static PARTS = {
    main: {
      template: 'systems/dsa5/templates/status/tokenHotbar.hbs'
    },
  };

  async _onWheelResize(ev) {
    let newVal = game.settings.get('dsa5', 'tokenhotbarSize');
    if (ev.originalEvent.deltaY > 0) {
      newVal = Math.min(100, newVal + 5);
    } else {
      newVal = Math.max(15, newVal - 5);
    }
    await game.settings.set('dsa5', 'tokenhotbarSize', newVal);
    await this.render(true);
  }

  async _cycleLayout(ev) {
    if (ev.button == 2) {
      let newVal = game.settings.get('dsa5', 'tokenhotbarLayout') + 1;
      if (newVal == 4) newVal = 0;
      await game.settings.set('dsa5', 'tokenhotbarLayout', newVal);
      await this.render(true);
    }
  }

  changeDarkness(ev) {
    const darkness = Number(ev.currentTarget.value);
    if (canvas.scene) canvas.scene.update({ 'environment.darknessLevel': darkness }, { animateDarkness: 3000 });

    tinyNotification(`${_loc('MASTER.darkness')} ${darkness}`);
  }

  async _onRender(context, options) {
    await super._onRender(context, options);
    const html = $(this.element);
    const container = html.find('.dragHandler');
    if (container[0]) new foundry.applications.ux.Draggable(this, this.element, container[0], this.options.resizable);

    container.on('wheel', async (ev) => {
      ev.stopPropagation();
      ev.preventDefault();
      await this._onWheelResize(ev);
      return false;
    });

    html.find('.itdarkness input').on('change', (ev) => this.changeDarkness(ev));

    const that = this;
    const fn = function (ev) {
      that.filterButtons(ev);
      return false;
    };
    const filterable = html.find('.filterable')
    filterable.on('pointerover', () => {
      $(document).off('keydown.tokenHotbars2', fn).on('keydown.tokenHotbars2', fn);
    });
    filterable.on('pointerout', () => {
      $(document).off('keydown.tokenHotbars2', fn);
    });
    html.find('.quantity-click').on('mousedown', (ev) => RuleChaos.quantityClick(ev));

    html.find('li').on('mousedown', async (ev) => {
      ev.stopPropagation();
      await this.executeQuickButton(ev);
      return false;
    });

    const primaryLis = html.find('li.primary')
    primaryLis.on('mouseenter', (ev) => {
      const cat = ev.currentTarget.dataset.category;
      this.category = cat;

      setTimeout(() => {
        html.find('.secondary').removeClass('shown');
        if (cat == this.category) html.find(`.secondary[data-category="${cat}"]`).addClass('shown');
      }, 700);
    });

    primaryLis.on('mouseleave', (ev) => {
      const cat = ev.currentTarget.dataset.category;
      this.category = undefined;

      setTimeout(() => {
        if (cat != this.category) {
          that.searching = '';
          $(ev.currentTarget).find('.secondary').removeClass('dsahidden');
          html.find(`.secondary[data-category="${cat}"]`).removeClass('shown');
        }
      }, 50);
    });
  }

  async handleEffect(ev, actor, id, tokenId) {
    const effect = actor.effects.get(id);
    const isSystemEffect = [...effect.statuses][0];
    if (ev.button == 0) {
      if (isSystemEffect) await actor.addCondition(isSystemEffect, 1, false, false);
      else effect.sheet.render(true);
    } else if (ev.button == 2) {
      if (isSystemEffect) await actor.removeCondition(isSystemEffect, 1, false);
      else await actor.sheet._deleteActiveEffect(id);
    }
  }

  async handleGMRoll(ev, target) {
    const elem = target || ev.currentTarget;
    const skill = elem.dataset.id;
    const mod = Math.round($(elem).closest('.tokenHotbarInner,#hotbar').find('.modifierVal').val());
    if (ev.ctrlKey) {
      game.dsa5.apps.DSA5ChatListeners.check3D20(undefined, skill, {
        modifier: mod,
      });
    } else if (ev.button == 2) {
      game.dsa5.macro.requestGC(skill, mod, { maxRolls: 7 });
    } else {
      game.dsa5.macro.requestRoll(skill, mod);
    }
  }

  async handleSkillRoll(ev, actor, id, tokenId, subweapon = undefined) {
    const options = {};
    if (ev.button == 2) options.messageMode = DICE_CONSTANTS.CHAT_MODES.BLIND;

    if ('rideLoyaltyID' == id) {
      Riding.rollLoyalty(actor, options);
    } else if ('attackWeaponless' == id) {
      actor.setupWeaponless('attack', options, tokenId).then((setupData) => {
        actor.basicTest(setupData);
      });
    } else {
      let result = actor?.items.get(id);
      if (result) {
        if (ev.ctrlKey) return result.sheet.render(true);

        switch (result.type) {
          case 'meleeweapon':
          case 'rangeweapon':
            if (ev.altKey) {
              if (actor) await actor.equipWeaponToHand(result.id, { equip: false });
              else await result.update({ 'system.worn.value': false });
            } else if (result.system.worn.value) {
              result = Actordsa5.buildSubweapon(result, subweapon);
              actor.setupWeapon(result, 'attack', options, tokenId).then((setupData) => {
                actor.basicTest(setupData);
              });
            } else {
              const wantsOffHand = ev.button == 2;
              const canOffHand = wantsOffHand && actor?.canEquipWeaponOffHand(result);

              if (actor) await actor.equipWeaponToHand(result.id, { hand: canOffHand ? 'offhand' : 'auto', equip: true });
              else await result.update({ 'system.worn.value': true, 'system.worn.offHand': !!canOffHand });
            }
            break;
          case 'trait':
            actor.setupWeapon(result, 'attack', options, tokenId).then((setupData) => {
              actor.basicTest(setupData);
            });
            break;
          case 'liturgy':
          case 'spell':
            actor.setupSpell(result, options, tokenId).then((setupData) => {
              actor.basicTest(setupData);
            });
            break;
          case 'skill':
            actor.setupSkill(result, options, tokenId).then((setupData) => {
              actor.basicTest(setupData);
            });
            break;
          case 'consumable':
          case 'plant':
            const proceed = await foundry.applications.api.DialogV2.confirm({
              window: {
                title: _loc('SHEET.ConsumeItem') + ': ' + result.name,
              },
              content: _loc('SHEET.ConsumeItem') + ': ' + result.name,
              rejectClose: false,
              modal: true,
            });
            if (proceed) {
              await result.setupEffect(null, {}, tokenId);
              await this.updateDSA5Hotbar(undefined, true);
            }
            break;
        }
      }
    }
  }

  async handleTradeStart(ev, actor, id, tokenId) {
    if (!game.user.targets.size) return ui.notifications.error('DIALOG.noTarget', { localize: true });

    for (const target of game.user.targets) {
      if (target.actor) {
        const app = new Trade(RollDialogBuilder.buildSpeaker(actor, tokenId), RollDialogBuilder.buildSpeaker(target.actor, target.id));
        app.startTrade();
      }
    }
  }

  async handleOnUse(ev, actor, id, tokenId) {
    const item = actor.items.get(id);
    if (item) {
      const onUse = new OnUseEffect(item);
      return onUse.executeOnUseEffect(OnUseEffect.buildExecutionOptions(ev));
    }
    const effect = actor.effects.get(id) || (id?.includes('.') ? await fromUuid(id) : null);
    if (effect) {
      const onUse = new OnUseEffect(effect);
      return onUse.executeOnUseEffect(OnUseEffect.buildExecutionOptions(ev));
    }
  }

  async handleEnchantment(ev, actor, id, tokenId) {
    const ids = id.split('_');
    const item = actor.items.get(ids[0]);
    if (ev.button == 2) {
      if (item) item.sheet.render(true);
    } else {
      const enchantments = item.getFlag('dsa5', 'enchantments');
      item.sheet.rollEnchantment(ids[1], enchantments);
    }
  }

  async handleGM(ev, actor, id, tokenId) {
    switch (id) {
      case 'masterMenu':
        DSA5_Utility.renderToggle(game.dsa5.apps.gameMasterMenu);
        break;
      case DSACalendarEntry.HOTBAR_ID:
        DSACalendarEntry.startCreation(null, game.time.calendar.timeToComponents(game.time.worldTime));
        break;
      case DSAQuestLogEntry.HOTBAR_ID:
        DSAQuestLogEntry.startCreation(null);
        break;
      case 'payMoney':
        this.payMoney(ev);
        break;
      case 'randomVictim':
        this.handleGMRandomVictim(ev);
        break;
      default:
        if (id in this.callbackFunctions) this.callbackFunctions[id](ev, actor, id, tokenId);
    }
  }

  payMoney(ev) {
    const money = `${$(ev.currentTarget).closest('.tokenHotbarInner,#hotbar').find('.modifierVal').val()}`;

    if (ev.button == 2) {
      PaymentRequestService.createRequest({ mode: 'getPaid', amount: money });
    } else {
      PaymentRequestService.createRequest({ mode: 'pay', amount: money });
    }
  }

  async handleGMRandomVictim(ev) {
    const randomPlayer = await game.dsa5.apps.gameMasterMenu.rollRandomPlayer(ev.button == 2);
    const actor = game.actors.get(randomPlayer);
    if (actor) {
      const k = await DSA5_Utility.showArtwork(actor);
      if (!ev.ctrlKey)
        setTimeout(() => {
          k.close();
        }, 2000);
    }
  }

  async handleSharedEffect(ev) {
    for (const token of canvas.tokens.controlled) {
      const actor = token.actor;
      const tokenId = token.id;
      const id = actor.effects.find((x) => x.name == ev.currentTarget.dataset.name)?.id;
      await this.handleEffect(ev, actor, id, tokenId);
    }
  }

  async executeQuickButton(ev, target) {
    if (ev.originalEvent) ev = ev.originalEvent;

    const { actor, tokenId } = resolveHotbarActorContext();
    const { id, subfunction, subweapon } = (target || ev.currentTarget).dataset;

    switch (subfunction) {
      case 'trade':
        this.handleTradeStart(ev, actor, id, tokenId);
        break;
      case 'addEffect':
        AddEffectDialog.showDialog();
        break;
      case 'effect':
        this.handleEffect(ev, actor, id, tokenId);
        break;
      case 'sharedEffect':
        this.handleSharedEffect(ev);
        break;
      case 'onUse':
      case 'onUseEffect':
        this.handleOnUse(ev, actor, id, tokenId);
        break;
      case 'gm':
        this.handleGM(ev, actor, id, tokenId);
        break;
      case 'none':
      case 'darkness':
        break;
      case 'skillgm':
        this.handleGMRoll(ev, target || ev.currentTarget);
        break;
      case 'enchantment':
        this.handleEnchantment(ev, actor, id, tokenId);
        break;
      default:
        this.handleSkillRoll(ev, actor, id, tokenId, subweapon);
    }
  }

  subWidth(items, itemWidth, defaultCount = 7) {
    return `style="width:${Math.ceil(items.length / defaultCount) * 200}px"`;
  }

  async _prepareContext(options) {
    const data = await super._prepareContext(options);

    const hotbarPosition = $('#hotbar').first().position();
    const itemWidth = game.settings.get('dsa5', 'tokenhotbarSize');
    const savedPosition = game.settings.get('dsa5', 'tokenhotbarPosition');

    const position = mergeObject({
      height: itemWidth + 45,
      zIndex: 61,
      left: hotbarPosition.left + 8,
      top: hotbarPosition.top - itemWidth - 25,
    }, savedPosition);
    mergeObject(options, { position });

    const actor = this.actor;
    const items = {
      attacks: [],
      spells: [],
      default: [],
      skills: [],
      functions: [],
      gm: [],
    };
    let consumable;
    let onUse;
    const consumables = [];
    const onUsages = [];
    let effects = [];
    const direction = game.settings.get('dsa5', 'tokenhotbarLayout');
    const vertical = direction % 2;

    let gmMode = false;
    if (actor) {
      const moreSkills = [];
      const moreSpells = [];
      const isRiding = Riding.isRiding(actor);
      const rideName = _loc('LocalizedIDs.riding');

      effects = await this._effectEntries(actor);
      if (game.combat) {
        const combatskills = actor.items.filter((x) => x.type == 'combatskill').map((x) => CombatskillData._calculateCombatSkillValues(x.toObject(), actor.system));
        const brawl = this._brawlEntry(combatskills);

        if (brawl) items.attacks.push(brawl);

        for (const x of actor.items) {
          if ('skill' == x.type && (TokenHotbar2.combatSkills.some((y) => x.name.startsWith(y)) || (isRiding && rideName == x.name))) {
            items.default.push(this._skillEntry(x, 'skill filterable'));
          }

          if (x.type == 'trait' && TokenHotbar2.traitTypes.has(x.system.traitType.value)) {
            items.attacks.push(this._traitEntry(x, actor.system));
          } else if (TokenHotbar2.attackTypes.has(x.type) && x.system.worn.value == true) {
            items.attacks.push(...this._combatEntry(x, combatskills, actor));
          } else if (TokenHotbar2.spellTypes.has(x.type)) {
            if (x.system.effectFormula.value) items.spells.push(this._skillEntry(x, 'spell filterable'));
            else moreSpells.push(this._skillEntry(x, 'spell filterable'));
          } else if ('skill' == x.type) {
            moreSkills.push(
              this._skillEntry(x, 'skill filterable', {
                addClass: x.system.group.value,
              }),
            );
          } else if (x.type == 'consumable') {
            consumables.push(
              this._actionEntry(x, 'consumable', {
                abbrev: x.system.quantity.value,
              }),
            );
          }

          if (OnUseEffect.hasOnUseEffect(x)) {
            onUsages.push(this._actionEntry(x, 'onUse', { subfunction: 'onUse' }));
          }
        }
        consumable = consumables.pop();

        if (isRiding) {
          const ridingEnttry = this._ridingEntry(actor);

          if (ridingEnttry) items.default.push(ridingEnttry);
        }
      } else {
        const descendingSkills = [];
        for (const x of actor.items) {
          if ('skill' == x.type && (TokenHotbar2.defaultSkills.has(x.name) || (isRiding && rideName == x.name))) {
            items.default.push(this._skillEntry(x, 'skill filterable'));
          }
          if ('skill' == x.type) {
            const elem = this._skillEntry(x, 'skill filterable', {
              addClass: x.system.group.value,
            });
            if (x.system.talentValue.value > 0) {
              descendingSkills.push(elem);
            }

            moreSkills.push(elem);
          } else if (TokenHotbar2.spellTypes.has(x.type)) {
            if (x.system.effectFormula.value) items.spells.push(this._actionEntry(x, 'spell filterable'));
            else moreSpells.push(this._actionEntry(x, 'spell filterable'));
          }

          if (OnUseEffect.hasOnUseEffect(x)) {
            onUsages.push(this._actionEntry(x, 'onUse', { subfunction: 'onUse' }));
          }
        }
        items.skills.push(
          ...descendingSkills
            .sort((a, b) => {
              return b.tw - a.tw;
            })
            .slice(0, 5),
        );
      }

      onUse = onUsages.pop();

      for (const ef of actor.allApplicableEffects()) {
        if (ef.notApplicable || (!game.user.isGM && ef.system?.visibility?.hidePlayers)) continue;
        if (OnUseEffect.hasOnUseEffect(ef)) {
          onUsages.push(this._actionEntry(ef, 'onUse', { id: ef.uuid, subfunction: 'onUseEffect' }));
        }
      }
      if (!onUse && onUsages.length) onUse = onUsages.pop();

      items.functions = this._functionEntries();

      if (items.spells.length == 0 && moreSpells.length > 0) {
        items.spells.push(moreSpells.pop());
      }
      if (items.spells.length > 0 && moreSpells.length > 0) {
        items.spells[0].more = moreSpells.sort((a, b) => {
          return a.name.localeCompare(b.name);
        });
        items.spells[0].subwidth = this.subWidth(moreSpells, itemWidth);
      }
      if (items.default.length > 0 && moreSkills.length > 0) {
        items.default[0].more = moreSkills.sort((a, b) => {
          return a.addClass.localeCompare(b.addClass) || a.name.localeCompare(b.name);
        });
        items.default[0].subwidth = this.subWidth(moreSkills, itemWidth, 20);
      }

      if (consumable) {
        if (consumables.length > 0) {
          consumable.more = consumables;
          consumable.subwidth = this.subWidth(consumables, itemWidth);
        }
        items.consumables = [consumable];
      }

      if (onUse) {
        if (onUsages.length > 0) {
          onUse.more = onUsages;
          onUse.subwidth = this.subWidth(onUsages, itemWidth);
        }
        items.onUsages = [onUse];
      }
    } else if (game.user.isGM && !game.settings.get('dsa5', 'disableTokenhotbarMaster')) {
      gmMode = true;
      const skills = this.skills || (await this.prepareSkills());
      items.gm = this._gmEntries().concat([
        {
          name: 'TT.tokenhotbarSkill',
          id: 'skillgm',
          icon: 'systems/dsa5/icons/categories/Skill.webp',
          cssClass: 'skillgm filterable',
          abbrev: '',
          subfunction: 'none',
          more: skills,
          subwidth: this.subWidth(skills, itemWidth, 20),
        },
      ]);
    }

    if (this.showEffects) {
      const label = _loc('CONDITION.add');
      const effect = {
        name: 'CONDITION.add',
        id: '',
        icon: 'icons/svg/aura.svg',
        cssClass: 'effect',
        abbrev: label[0],
        subfunction: 'addEffect',
      };
      if (effects.length > 0) {
        effect.more = effects;
        effect.subwidth = this.subWidth(effects, itemWidth);
      } else if (canvas.tokens.controlled.length > 1) {
        let sharedEffects = await game.dsa5.apps.tokenHotbar._effectEntries(canvas.tokens.controlled[0].actor, { subfunction: 'sharedEffect' });

        for (const token of canvas.tokens.controlled) {
          const tokenEffects = (await token.actor.actorEffects()).map((x) => x.name);
          sharedEffects = sharedEffects.filter((x) => tokenEffects.includes(x.name));
        }
        effect.more = sharedEffects;
        effect.subwidth = this.subWidth(sharedEffects, itemWidth);
      }
      items.effects = [effect];
    }

    const count =
      Object.keys(items).reduce((prev, cur) => {
        return prev + items[cur].length;
      }, 0) + (gmMode ? 3 : 0);

    if (vertical) {
      options.position.width = itemWidth;
      options.position.height = itemWidth * count + 14;
    } else {
      options.position.width = itemWidth * count + 14;
      options.position.height = itemWidth;
    }

    Object.assign(data, {
      items,
      itemWidth,
      direction,
      count,
      gmMode,
      darkness: canvas?.scene?.environment.darknessLevel || 0,
      opacity: game.settings.get('dsa5', 'tokenhotbaropacity'),
    });

    return data;
  }

  _functionEntries() {
    const trade = _loc('MERCHANT.exchangeWithTarget');
    return [
      {
        name: trade,
        id: 'trade',
        cssClass: 'function',
        abbrev: trade[0],
        iconClass: 'fas fa-coins',
        subfunction: 'trade',
      },
    ];
  }

  _brawlEntry(combatskills) {
    const brawl = combatskills.find((x) => x.name == _loc('LocalizedIDs.wrestle'));
    if (brawl) {
      return {
        name: _loc('attackWeaponless'),
        id: 'attackWeaponless',
        icon: 'systems/dsa5/icons/categories/attack_weaponless.webp',
        attack: brawl.system.attack.value,
        damage: '1d6',
        cssClass: 'zbrawl',
      };
    }
  }

  _ridingEntry(actor) {
    const horse = Riding.getHorse(actor);
    if (horse) {
      const x = Riding.getLoyaltyFromHorse(horse);
      if (x) {
        return {
          name: `${x.name} (${x.system.talentValue.value})`,
          id: 'rideLoyaltyID',
          icon: x.img,
          cssClass: 'skill',
          abbrev: x.name[0],
        };
      }
    }
  }

  _gmEntries() {
    return game.user.isGM ? this.gmItems.filter((x) => !x.disabled) : [];
  }

  _actionEntry(x, cssClass, options = {}) {
    return {
      name: x.name,
      id: x.id,
      icon: x.img,
      cssClass,
      abbrev: x.name[0],
      ...options,
    };
  }

  _enchantmentEntry(x, cssClass, item, options = {}) {
    return {
      name: `${item.name} - ${x.name}`,
      id: `${item.id}_${x.id}`,
      icon: ITEM_CONSTANTS.DEFAULT_IMAGES[x.talisman ? 'liturgy' : 'spell'],
      cssClass,
      abbrev: x.name[0],
      ...options,
    };
  }

  _skillEntry(x, cssClass, options = {}) {
    const tw = x.system?.talentValue.value;
    const name = tw ? `${x.name} (${tw})` : x.name;
    return {
      name: name,
      id: x.id,
      icon: x.img,
      cssClass,
      addClass: x.system?.group?.value,
      abbrev: x.name[0],
      tw,
      ...options,
    };
  }

  _traitEntry(x, actorData) {
    const preparedItem = ItemDataModel._parseDmg(x.toObject(), actorData);
    return {
      name: x.name,
      id: x.id,
      icon: x.img,
      cssClass: `weapon i${x.id}`,
      abbrev: x.name[0],
      attack: x.system.at.value,
      damage: preparedItem.damagedie,
      dadd: preparedItem.damageAdd,
    };
  }

  _combatEntry(x, combatskills, actor, options = {}) {
    if (combatskills.length == 0) return [];

    const preparedItem =
      x.type === 'meleeweapon'
        ? Actordsa5._prepareMeleeWeapon(x.toObject(), combatskills, actor)
        : Actordsa5._prepareRangeWeapon(x.toObject(), [], combatskills, actor);

    const buildEntry = (name, id, img, attack, damagedie, damageAdd, subweapon) => {
      const entry = {
        name,
        id,
        icon: img,
        cssClass: `weapon i${id}`,
        abbrev: name?.[0],
        attack,
        damage: damagedie,
        dadd: damageAdd,
        ...options,
      };
      if (subweapon) entry.subweapon = subweapon;
      return entry;
    };

    const entries = [buildEntry(x.name, x.id, x.img, preparedItem.attack, preparedItem.damagedie, preparedItem.damageAdd)];

    const subweapons = preparedItem.subweapons ?? {};
    entries.push(
      ...Object.entries(subweapons).map(([key, value]) =>
        buildEntry(value.name, x.id, x.img, value.attack, value.damagedie, value.damageAdd, key)
      )
    );

    return entries;
  }

  async _effectEntries(actor, options = {}) {
    return (await actor.actorEffects()).map((x) => {
      const level = x.system.condition.value || '';
      const name = level ? `${x.name} (${level})` : x.name;
      return {
        name: name,
        id: x.id,
        icon: x.img,
        cssClass: 'effect',
        abbrev: `${x.name[0]} ${level}`,
        subfunction: 'effect',
        indicator: level,
        ...options,
      };
    });
  }

  filterButtons(ev) {
    switch (ev.which) {
      case 8:
        this.searching = this.searching.slice(0, -1);
        break;
      default:
        if (!ev.key.match(/^[a-zA-Z0-9öäüÖÄÜ]$/)) return;

        this.searching += ev.key;
    }
    ev.preventDefault();
    ev.stopPropagation();
    const search = this.searching.toLowerCase();
    tinyNotification(search);
    const btns = $(ev.currentTarget).find('.subbuttons li');
    btns.find('.dsahidden').removeClass('dsahidden');
    btns
      .filter(function () {
        return $(this).find('label').text().toLowerCase().trim().indexOf(search) == -1;
      })
      .addClass('dsahidden');
  }

  async render(force, options = {}) {
    const rend = await super.render(force, options);
    if (this.element) {
      $(this.element).css({ zIndex: 61 });
    }
    return rend;
  }

  setPosition(position) {
    const currentPosition = super.setPosition(position);
    game.settings.set('dsa5', 'tokenhotbarPosition', {
      left: currentPosition.left,
      top: currentPosition.top,
    });
    return currentPosition;
  }

  async updateDSA5Hotbar(actorId, force = false) {
    ui.hotbar.updateHotbar(actorId, force);
    if (game.settings.get('dsa5', 'disableTokenhotbar')) return;

    const controlled = canvas.tokens.controlled;
    this.showEffects = controlled.length > 0;
    this.actor = resolveHotbarActorContext().actor;

    await this.render(true, { focus: false });
  }
}

export class AddEffectDialog extends DefaultAppv2 {
  #conditionSearch;

  static DEFAULT_OPTIONS = {
    classes: ['dsa5', 'tokenStatusEffects'],
    window: {
      title: 'CONDITION.add',
      resizable: true,
    },
    position: {
      width: 700
    },
    actions: {
      reactClick: this.#addEffect,
      reactCustom: this.#configureEffect
    }
  };

  static PARTS = {
    main: {
      template: 'systems/dsa5/templates/dialog/addstatusdialog.hbs',
    }
  };

  async _prepareContext(_options) {
    const data = await super._prepareContext(_options);
    data.effects = duplicate(CONFIG.statusEffects)
      .map((x) => {
        return {
          name: _loc(x.name),
          img: x.img,
          description: _loc(x.description),
          id: x.id,
        };
      })
      .sort((a, b) => a.name.localeCompare(b.name));
    return data;
  }

  static async showDialog() {
    new AddEffectDialog().render(true);
  }

  async _onRender(context, options) {
    await super._onRender(context, options);

    const html = $(this.element);

    html.find('.quantity-click').on('mousedown', (ev) => RuleChaos.quantityClick(ev));

    const positionUpdate = {};
    if (this.options.position.width === 'auto') positionUpdate.width = 'auto';
    if (this.options.position.height === 'auto') positionUpdate.height = 'auto';
    if (!foundry.utils.isEmpty(positionUpdate)) this.setPosition(positionUpdate);

    this.#conditionSearch ??= new foundry.applications.ux.SearchFilter({
      inputSelector: ".conditionSearch",
      contentSelector: ".window-content",
      callback: this._filterConditions.bind(this)
    });
    this.#conditionSearch.bind(this.element);
  }

  _filterConditions(_event, query, rgx, html) {
    for (const entry of html.querySelectorAll(".filterable")) {
      if (!query) {
        entry.hidden = false;
        continue;
      }

      const title = entry.querySelector('span').textContent || '';
      const isMatch = [title].some(q => rgx.test(foundry.applications.ux.SearchFilter.cleanQuery(q)));
      entry.hidden = !isMatch;
    }
  }

  _tearDown(options) {
    super._tearDown(options);
    this.#conditionSearch?.unbind();
  }

  static async modifyEffectDialog(id, callback) {
    new foundry.applications.api.DialogV2({
      //classes: ["dsa5", "dialog"],
      window: {
        title: 'CONDITION.' + id,
      },
      position: {
        width: 400,
      },
      content: await renderTemplate('systems/dsa5/templates/dialog/configurestatusdialog.hbs'),
      buttons: [
        {
          action: 'add',
          icon: 'fa fa-check',
          label: 'CONDITION.add',
          callback: async (event, button, dialog) => {
            const form = button.form.elements;
            const options = {};

            const duration = Number(form.duration.value) || 0;
            const unit = form.unit.value;

            const label = form.effectname.value;
            if (duration > 0) mergeObject(options, RuleChaos._buildDuration(duration, unit));
            if (label) options.name = label;

            await callback(id, options);
          },
        },
      ],
    }).render(true);
  }

  static async #configureEffect(ev, target) {
    const id = target.dataset.value;
    this.close();
    AddEffectDialog.modifyEffectDialog(id, async (id, options) => this.addEffect(id, options));
  }

  static #addEffect(ev, target) {
    this.addEffect(target.dataset.value)
  }

  async addEffect(id, options = {}) {
    const isCustomEffect = id == 'custom';
    if (canvas.tokens.controlled.length == 1 && isCustomEffect) {
      DSA5StatusEffects.createCustomEffect(canvas.tokens.controlled[0].actor);
    } else if (isCustomEffect) {
      ui.notifications.error('DSAError.customEffect', { localize: true });
    } else {
      for (const token of canvas.tokens.controlled) {
        await token.actor.addTimedCondition(id, 1, false, false, options);
      }
    }
    this.close();
  }
}
