import { DefaultAppv2 } from '../actor/baseapp.js';
import AdvantageRulesDSA5 from '../system/rules/advantage-rules-dsa5.js';
import DSA5 from '../config/config-dsa5.js';
import ItemRulesDSA5 from '../system/rules/item-rules-dsa5.js';
import SpecialabilityRulesDSA5 from '../system/rules/specialability-rules-dsa5.js';
import DSA5_Utility from '../system/helpers/utility-dsa5.js';
import { clickableAbility, tabSlider } from '../system/helpers/view_helper.js';
const { duplicate, getProperty } = foundry.utils;

export default class WizardDSA5 extends DefaultAppv2 {
  constructor(app) {
    super(app);
    this.actor = null;
    this.errors = [];
    this.attributes = [];
    this.updating = false;
  }

  static DEFAULT_OPTIONS = {
    classes: ['dsa5', 'largeDialog', 'generationWizard'],
    window: {
      title: 'PLAYER.title',
      resizable: true,
    },
    position: {
      width: 770,
      height: 740,
    },
    actions: {
      searchableAbility: this._onSearchableAbility,
    }
  };

  static _onSearchableAbility(ev, target) {
    clickableAbility(target);
  }

  async findCompendiumItem(name, types) {
    for (const type of types) {
      //todo make sure this loads the right thing e.g. armory instead of core
      let result = await game.dsa5.itemLibrary.findCompendiumItem(name, type);
      result = result.find((x) => x.name == name && x.type == type && x.system);

      if (result) return result;
    }
    return undefined;
  }

  _parseAttributes(attr, splitter = ',') {
    const result = [];
    const splstr = _loc('combatskillcountdivider') + ':';
    for (const k of attr.split(splitter)) {
      if (k.includes(splstr)) {
        const vals = k.split(':');
        result.push({
          choices: vals[1].split('/').map((x) => x.trim()),
          allowedCount: Number(vals[0].match(/\d/g)),
        });
      }
    }
    return result;
  }

  filterTabs(data) {
    for(const tab of Object.keys(data.tabs)) {
      if(!data[data.tabs[tab].id]) delete data.tabs[tab]
    }
  }

  async parseToItem(value, types) {
    if (value.trim() == '' || value.trim() == "-") return [];

    return await Promise.all(
      value.split(', ').map(async (x) => {
        const parsed = DSA5_Utility.parseAbilityString(x.trim());
        let item = await this.findCompendiumItem(parsed.original, types);
        if (!item) {
          item = await this.findCompendiumItem(parsed.name, types);
        }
        if (!item) {
          if (this.attributes.includes(parsed.name)) {
            let cost = 0;

            for (let i = this.actor.system.characteristics[game.dsa5.config.knownShortcuts[parsed.name.toLowerCase()][1]].value + 1; i < parsed.step + 1; i++) {
              cost += DSA5.advancementCosts.E[i];
            }
            item = {
              name: parsed.name,
              step: parsed.step,
              attributeRequirement: true,
              apCost: cost,
              system: {
                APValue: {
                  value: cost,
                },
              },
            };
          } else {
            console.warn(`Not found <${x}>`);
            const langCats = types.map((x) => DSA5_Utility.categoryLocalization(x)).join('/');
            this.errors.push(`${langCats}: ${x}`);
            item = {
              name: x.trim(),
              notFound: true,
              tooltip: _loc('DSAError.itemNotFound'),
              apCost: '?',
            };
          }
        } else {
          const uuid = item.uuid;
          item = duplicate(item);
          item.uuid = uuid;
          item.tooltip = _loc('Details');
          item = ItemRulesDSA5.reverseAdoptionCalculation(this.actor, parsed, item);
          if (item.system.APValue) {
            item.APunparseable = isNaN(item.system.APValue.value);
            item.apCost = item.APunparseable ? item.system.APValue.value : parsed.step * Number(item.system.APValue.value);
          }
        }
        item.replaceName = parsed.original;
        item.step = parsed.step;
        const actorHasItem = this.actor.items.find((y) => types.includes(y.type) && y.name == parsed.original) != undefined;
        item.disabled = actorHasItem || item.notFound || item.APunparseable;
        if (actorHasItem) item.tooltip = _loc('YouAlreadyHaveit');
        return item;
      }),
    );
  }

  mergeLevels(itemsToAdd, item, keyMax) {
    let merged = false;
    const existing = itemsToAdd.find((x) => x.name == item.name && x.type == item.type);
    if (existing) {
      merged = true;
      const level = Number(getProperty(item, 'system.step.value'));
      if (level) {
        existing.system.step.value = Math.min((existing.system.step.value += level), existing.system[keyMax].value);
      }
    } else {
      itemsToAdd.push(item);
    }
    return merged;
  }

  async addSelections(elems, render = true) {
    const itemsToAdd = [];

    for (const k of elems) {
      const val = $(k).val();
      if (val == '') continue;

      let item = (await fromUuid($(k).val())).toObject();
      const parsed = DSA5_Utility.parseAbilityString(item.name);
      item.name = $(k).attr('name');

      switch (item.type) {
        case 'advantage':
        case 'disadvantage':
          item.system.step.value = Number(k.dataset.step);
          item = ItemRulesDSA5.reverseAdoptionCalculation(this.actor, parsed, item);

          if (!this.mergeLevels(itemsToAdd, item, 'max')) AdvantageRulesDSA5.vantageAdded(this.actor, item);
          break;
        case 'specialability':
          item.system.step.value = Number(k.dataset.step);

          if (k.dataset.free == 'true') item.system.APValue.value = 0;

          item = ItemRulesDSA5.reverseAdoptionCalculation(this.actor, parsed, item);

          if (!this.mergeLevels(itemsToAdd, item, 'maxRank')) SpecialabilityRulesDSA5.abilityAdded(this.actor, item);
          break;
        case 'magictrick':
          this.mergeLevels(itemsToAdd, item);
          break;
      }
    }
    await this.actor.createEmbeddedDocuments('Item', itemsToAdd, { render });
  }

  async fixPreviousCosts(previous, toFix) {
    for (const item of toFix) {
      const hasFixable = previous.find((x) => x.type == item.type && x.name == item.name);

      if (hasFixable) item.apCost -= hasFixable.apCost;
    }
  }

  async alreadyAdded(string, category) {
    if (string == '') return false;

    let result = false;
    try {
      result = await foundry.applications.api.DialogV2.wait({
        window: {
          title: 'DIALOG.warning',
        },
        content: `<p>${_loc('DIALOG.alreadyAddedCharacterpart', { category: DSA5_Utility.categoryLocalization(category) })}</p>`,
        buttons: [
          {
            action: 'ok',
            default: true,
            icon: 'fas fa-check',
            label: 'ok',
            callback: () => false,
          },
          {
            action: 'cancel',
            icon: 'fas fa-close',
            label: 'cancel',
            callback: () => true,
          },
        ],
      });
    } catch (error) {
      /* empty */
    }

    return result;
  }

  async updateSkill(skills, itemType, factor = 1, bonus = true) {
    const itemsToUpdate = [];
    for (const skill of skills) {
      const parsed = DSA5_Utility.parseAbilityString(skill.trim());
      const res = this.actor.items.find((i) => {
        return i.type == itemType && i.name == parsed.name;
      });
      if (res) {
        itemsToUpdate.push({
          _id: res.id,
          'system.talentValue.value': Math.max(0, factor * parsed.step + (bonus ? Number(res.system.talentValue.value) : 0)),
        });
      } else {
        console.warn(`Could not find ${itemType} ${skill}`);
        this.errors.push(`${DSA5_Utility.categoryLocalization(itemType)}: ${skill}`);
      }
    }
    await this.actor.updateEmbeddedDocuments('Item', itemsToUpdate, { render: false, });
  }

  async _prepareContext(_options) {
    const data = await super._prepareContext(_options);
    await game.dsa5.itemLibrary.buildEquipmentIndex();
    return data;
  }

  _validateInput(parent, app = this) {
    const regex = /^exclusive_/;
    for (const tab of parent.find('.tab')) {
      const tb = $(tab);
      const exclusives = new Set();
      for (const k of tb.find('.exclusive')) {
        exclusives.add(k.className.split(/\s+/).filter((x) => regex.test(x))[0]);
      }
      for (const k of exclusives) {
        const choice = tb.find('.allowedCount_' + k.split('_')[1]);
        const allowed = Number(choice.attr('data-count'));
        if (tb.find(`.${k}:checked`).length != allowed) {
          this._showInputValidation(choice, tb, app);
          return false;
        }
      }
    }
    return true;
  }

  _showInputValidation(choice, parent, app) {
    ui.notifications.error('DSAError.MissingChoices', { localize: true });
    const tabElem = choice.closest('.tab')[0].dataset;
    app.changeTab(tabElem.tab, tabElem.group);
    WizardDSA5.flashElem(parent.find(`.tabs a[data-tab='${tabElem.tab}']`));
    WizardDSA5.flashElem(choice.closest('div'));
  }

  _getAPCostContainer(target) {
    return $(target).closest('.dsa-card-panel[data-cost]');
  }

  _apCostFrom(element, fallback = 0) {
    const cost = Number($(element).attr('data-cost'));
    return Number.isFinite(cost) ? cost : fallback;
  }

  _updateAPCost(parent, apCost) {
    const elem = parent.find('.apCost');
    elem.text(apCost);
    WizardDSA5.flashElem(elem, 'emphasize2');
  }

  async _onRender(context, options) {
    await super._onRender(context, options);
    const html = $(this.element);
    this.wizardListeners(html);
  }

  wizardListeners(html) {
    tabSlider(html);
    html.find('button.ok').on('click', () => {
      if (!this.updating) {
        this.updating = true;
        this.updateCharacter($(this.element)).then(() => (this.updating = false));
      }
    });

    const itemDragStart = (event) => {
      event.stopPropagation();
      const type = event.currentTarget.dataset.type;
      const uuid = event.currentTarget.dataset.uuid;
      if (!uuid || !type) return;

      event.originalEvent.dataTransfer.setData(
        'text/plain',
        JSON.stringify({
          type,
          uuid,
        }),
      );
    };
    const showItem = html.find('.show-item');
    showItem.on('click', async (ev) => {
      const itemId = ev.currentTarget.dataset.uuid;
      const item = await fromUuid(itemId);
      item.sheet.render(true);
    });
    showItem.attr('draggable', true).on('dragstart', (event) => itemDragStart(event));

    html.find('.exclusive').on('change', (ev) => {
      const parent = $(ev.currentTarget).closest('.tab');
      const sel = $(ev.currentTarget).attr('data-sel');
      const maxDomElem = parent.find(`.allowedCount_${sel}`);
      const maxSelections = Number(maxDomElem.attr('data-count'));
      if (parent.find(`.exclusive_${sel}:checked`).length > maxSelections) {
        ev.currentTarget.checked = false;
        WizardDSA5.flashElem(maxDomElem);
        return;
      }
    });
  }

  static flashElem(elem, cssClass = 'emphasize') {
    elem.addClass(cssClass);
    setTimeout(function () {
      elem.removeClass(cssClass);
    }, 600);
  }

  finalizeUpdate() {
    if (this.errors.length == 0) {
      this.close();
    } else {
      $(this.element)
        .find('.dialog-buttons')
        .html(`<div class="error"><p>${_loc('DSAError.notUnderstood')}</p><ul><li>${this.errors.join('</li><li>')}</li></ul></div>`);
    }
  }
}
